do $$
declare
  v_master_count integer;
  v_schedule_count integer;
begin
  select count(*) into v_master_count
  from staging.legacy_customer_master;

  select count(*) into v_schedule_count
  from staging.legacy_customer_schedule;

  if v_master_count <> 141 then
    raise exception 'CustomerMaster staging count mismatch. Expected 141, found %.', v_master_count;
  end if;

  if v_schedule_count <> 417 then
    raise exception 'CustomerSchedule staging count mismatch. Expected 417, found %.', v_schedule_count;
  end if;
end;
$$;

